ALTER TABLE "pre_anaesthesia_assessment_grades" ADD CONSTRAINT "pre_anaesthesia_assessment_grades_recommendation_check" CHECK (recommendation IN ('proceed', 'optimise-first', 'mdt-review', 'cancel', '')) NOT VALID;
ALTER TABLE "pre_anaesthesia_assessment_grade_rules" ADD CONSTRAINT "pre_anaesthesia_assessment_grade_rules_instrument_check" CHECK (instrument IN ('asa', 'mallampati', 'rcri', 'stopbang', 'frailty')) NOT VALID;
ALTER TABLE "pre_anaesthesia_assessment_grade_flags" ADD CONSTRAINT "pre_anaesthesia_assessment_grade_flags_category_check" CHECK (category IN ( 'difficult-airway', 'severe-cardiac', 'severe-respiratory', 'severe-renal', 'severe-hepatic', 'severe-anaemia', 'coagulopathy', 'uncontrolled-diabetes', 'severe-frailty', 'recent-covid-19', 'fasting-violation', 'missing-crossmatch', 'high-risk-medication', 'capacity-concern', 'paediatric', 'pregnancy', 'safeguarding', 'malignant-hyperthermia', 'latex-allergy', 'sux-apnoea', 'pseudocholinesterase-deficiency', 'malnutrition-risk', 'other', '' )) NOT VALID;
ALTER TABLE "pre_anaesthesia_assessment_grade_flags" ADD CONSTRAINT "pre_anaesthesia_assessment_grade_flags_priority_check" CHECK (priority IN ('low', 'medium', 'high', '')) NOT VALID;
